CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','employee')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users, token_hash text NOT NULL UNIQUE, refresh_hash text NOT NULL UNIQUE, device text NOT NULL DEFAULT 'Onbekend', expires_at timestamptz NOT NULL, refresh_expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE locations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_id uuid REFERENCES locations, name text NOT NULL, type text NOT NULL DEFAULT 'locatie', metadata jsonb NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_id uuid REFERENCES assets, location_id uuid REFERENCES locations, name text NOT NULL, manufacturer text, model text, serial_number text, status text NOT NULL DEFAULT 'active', notes text NOT NULL DEFAULT '', installation_date date, warranty_date date, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'reparatie', tags text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','planned','in_progress','blocked','completed','cancelled','archived')), priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','critical')), location_id uuid REFERENCES locations, asset_id uuid REFERENCES assets, created_by uuid NOT NULL REFERENCES users, updated_by uuid NOT NULL REFERENCES users, assigned_to uuid[] NOT NULL DEFAULT '{}', checklist jsonb NOT NULL DEFAULT '[]', dependencies uuid[] NOT NULL DEFAULT '{}', blocked_reason text, available_from timestamptz, planned_at timestamptz, deadline timestamptz, estimated_minutes integer CHECK(estimated_minutes>=0), completed_at timestamptz, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX tasks_status_deadline ON tasks(status,deadline);
CREATE INDEX tasks_asset ON tasks(asset_id);
CREATE INDEX tasks_assigned ON tasks USING gin(assigned_to);
CREATE INDEX tasks_search ON tasks USING gin(to_tsvector('simple',title||' '||description));
CREATE TABLE task_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES tasks, user_id uuid NOT NULL REFERENCES users, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE time_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES tasks, user_id uuid NOT NULL REFERENCES users, started_at timestamptz NOT NULL, ended_at timestamptz, minutes numeric CHECK(minutes>=0), note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), CHECK(ended_at IS NULL OR ended_at>=started_at));
CREATE UNIQUE INDEX single_running_timer ON time_entries(user_id) WHERE ended_at IS NULL;
CREATE TABLE task_schedules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid REFERENCES tasks, user_id uuid NOT NULL REFERENCES users, title text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, shared boolean NOT NULL DEFAULT false, participants uuid[] NOT NULL DEFAULT '{}', version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
CREATE INDEX schedules_dates ON task_schedules(starts_at,ends_at);
CREATE TABLE attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid REFERENCES tasks, asset_id uuid REFERENCES assets, uploaded_by uuid NOT NULL REFERENCES users, name text NOT NULL, storage_name text NOT NULL UNIQUE, mime_type text NOT NULL, size integer NOT NULL, hash text NOT NULL, phase text NOT NULL DEFAULT 'during', annotation jsonb, created_at timestamptz NOT NULL DEFAULT now(), CHECK(task_id IS NOT NULL OR asset_id IS NOT NULL));
CREATE TABLE audit_events(id bigserial PRIMARY KEY, actor_id uuid REFERENCES users, entity_type text NOT NULL, entity_id text NOT NULL, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_entity ON audit_events(entity_type,entity_id,created_at);
CREATE TABLE sync_operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users, operation_id text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,operation_id));
